//! U-8 part 3: Project Wycheproof `ecdsa_secp256k1_sha256` vectors, JVM 3.7.2 vs Rust.
//!
//! Docker-free. `tests/oracle/lf-vectors/wycheproof/expected.tsv` holds what the JVM's `secp256k1` builtin answered for each of
//! the 476 tests (`ok:True`, `ok:False`, or `fatal:<first line of the error>` when it ends the whole script; regenerated by
//! `scripts/verify-wycheproof.sh --update`). Every test is a pure value `Wy:c<tcId>` of `wy.dar`, evaluated here with `lf-eval`;
//! its outcome must agree with the JVM's.
//!
//! [CANTON-NOTE: SEMANTICS] The oracle is the JVM, not Wycheproof's verdict. The test prints how the JVM's answers relate to the
//! Wycheproof verdicts (a `valid` test that the JVM does not accept, an `invalid` one that it accepts) so the differences stay
//! visible; they are properties of the JVM builtin, not of this test.
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use lf_eval::{Value, World};

fn dir() -> PathBuf {
    std::env::var_os("WYCHEPROOF_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../../tests/oracle/lf-vectors/wycheproof")
        })
}

fn table(name: &str) -> Vec<Vec<String>> {
    std::fs::read_to_string(dir().join(name))
        .unwrap_or_else(|e| panic!("read {name}: {e}"))
        .lines()
        .filter(|l| !l.is_empty())
        .map(|l| l.split('\t').map(str::to_string).collect())
        .collect()
}

fn rust_outcome(world: &World, tc: &str) -> String {
    match world.eval("Wy", &format!("c{tc}"), &[]) {
        Ok(Value::Bool(true)) => "ok:True".to_string(),
        Ok(Value::Bool(false)) => "ok:False".to_string(),
        Ok(other) => format!("fatal:unexpected value {other:?}"),
        Err(e) => format!("fatal:{e}").replace('\n', " "),
    }
}

/// `ok:...` as is; for a fatal outcome the kind of the uncatchable error named in the JVM's or Rust's text.
fn kind_of(outcome: &str) -> String {
    let Some(text) = outcome.strip_prefix("fatal:") else {
        return outcome.to_string();
    };
    let lower = text.to_lowercase();
    if lower.contains("malformed signature") {
        "fatal:malformed-signature".to_string()
    } else if lower.contains("general error") || lower.contains("generalerror") {
        // an `error` raised by the Daml library wrapper (the signature is not DER); the message is what both sides name
        let after = lower.rsplit("generalerror").next().unwrap_or("");
        let after = after
            .strip_prefix(" (error category")
            .and_then(|r| r.split_once(')'))
            .map_or(after, |(_, rest)| rest);
        let message: String = after
            .trim_start_matches(':')
            .trim()
            .chars()
            .take(40)
            .collect();
        format!("fatal:daml-error:{message}")
    } else if lower.contains("malformed") && lower.contains("key") {
        "fatal:malformed-key".to_string()
    } else {
        format!("fatal:other:{}", lower.chars().take(60).collect::<String>())
    }
}

#[test]
fn wycheproof_secp256k1_sha256_agrees_with_the_jvm() {
    let world =
        World::open(&dir().join("wy.dar")).expect("wy.dar (scripts/verify-wycheproof.sh --update)");
    let expected: BTreeMap<String, String> = table("expected.tsv")
        .into_iter()
        .map(|r| (r[0].clone(), r[1].clone()))
        .collect();
    let vectors = table("vectors.tsv");
    assert_eq!(expected.len(), 476, "expected.tsv rows");
    assert_eq!(vectors.len(), 476, "vectors.tsv rows");

    let mut mismatches = Vec::new();
    let mut by_class: BTreeMap<String, usize> = BTreeMap::new();
    let mut jvm_vs_wycheproof = Vec::new();
    for row in &vectors {
        let (tc, verdict, flags) = (&row[0], &row[1], &row[2]);
        let jvm = &expected[tc];
        let rust = rust_outcome(&world, tc);
        *by_class.entry(kind_of(jvm)).or_default() += 1;
        if kind_of(jvm) != kind_of(&rust) {
            mismatches.push(format!("  tc {tc} ({flags}): jvm `{jvm}` rust `{rust}`"));
        }
        // valid must verify True; invalid must not verify True (False or an ended script both count as "not accepted")
        let accepted = jvm == "ok:True";
        if (verdict == "valid") != accepted {
            jvm_vs_wycheproof.push(format!("tc {tc} wycheproof={verdict} jvm={jvm} [{flags}]"));
        }
    }
    println!("wycheproof: JVM outcomes by class: {by_class:?}");
    println!(
        "wycheproof: {} tests where the JVM answer differs from Wycheproof's verdict",
        jvm_vs_wycheproof.len()
    );
    for line in &jvm_vs_wycheproof {
        println!("wycheproof:   {line}");
    }
    assert!(
        mismatches.is_empty(),
        "{} of 476 tests differ between the JVM and lf-eval:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
